import {tunnelTiles} from './tunnels.js?v=courtyard-apartments-1';
export const LANDSCAPE={raise:{name:'Raise terrain',cost:5},lower:{name:'Lower terrain',cost:5},levelTerrain:{name:'Level terrain',cost:5},surfaceWater:{name:'Create surface water',cost:10},plantTrees:{name:'Plant trees',cost:5}};
export function planLandscape(c,tool,points){const n=Math.sqrt(c.tiles.length),fail=error=>({ok:false,error,cost:0,points:[]});if(!points.length||points.some(p=>!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.y<0||p.x>=n||p.y>=n))return fail('Choose tiles inside the city.');const selected=[...new Set(points.map(p=>p.y*n+p.x))],protectedTile=t=>(c.tunnels||[]).some(tunnel=>tunnelTiles(c,tunnel).includes(t.y*n+t.x))||t.radiation||t.type||t.rubble||t.fire||t.pipe||t.subway||t.rail||t.highway;let changes=[];
 if(tool==='plantTrees'||tool==='surfaceWater'){for(const i of selected){const t=c.tiles[i];if(protectedTile(t)||t.terrain==='water')return fail('Landscape tools need undeveloped dry land, clear of underground utilities.');if(tool==='surfaceWater'&&t.elevation>0)return fail('Level this area to elevation zero before creating surface water.');if(tool==='plantTrees'&&t.nature&&(t.treeLevel||0)>=3)continue;changes.push({x:t.x,y:t.y,elevation:t.elevation,terrain:tool==='surfaceWater'?'water':t.terrain,waterKind:'fresh',nature:tool==='plantTrees',treeLevel:tool==='plantTrees'?Math.min(3,(t.nature?t.treeLevel||1:0)+1):0});}}
 else{const heights=c.tiles.map(t=>t.elevation||0),queue=[],target=heights[selected[0]];for(const i of selected){const h=tool==='levelTerrain'?target:Math.max(0,Math.min(8,heights[i]+(tool==='raise'?1:-1)));if(h!==heights[i]){heights[i]=h;queue.push(i);}}
 for(let k=0;k<queue.length;k++){const i=queue[k],t=c.tiles[i];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=t.x+dx,y=t.y+dy,j=y*n+x;if(x<0||y<0||x>=n||y>=n)continue;const next=Math.max(heights[i]-1,Math.min(heights[i]+1,heights[j]));if(next!==heights[j]){heights[j]=next;queue.push(j);}}}
 for(let i=0;i<heights.length;i++)if(heights[i]!==c.tiles[i].elevation){const t=c.tiles[i];if(protectedTile(t)||t.terrain==='water')return fail('Terrain changes would affect a building, utility, bridge, pond or radiation. Clear the affected area first.');changes.push({x:t.x,y:t.y,elevation:heights[i]});}}
 if(!changes.length)return fail('No landscape changes at these tiles.');const cost=changes.reduce((sum,p)=>sum+LANDSCAPE[tool].cost*(tool==='plantTrees'||tool==='surfaceWater'?1:Math.abs(p.elevation-c.tiles[p.y*n+p.x].elevation)),0);if(cost>c.funds)return fail('Insufficient funds for this landscape change.');return{ok:true,cost,points:changes};}
